export function generationData(input:SupportGenerationInput){return {knowledgeVersion:input.knowledge?.version??SUPPORT_KNOWLEDGE_VERSION,documents:input.knowledge?.documents??SUPPORT_KNOWLEDGE,accountFacts:input.context,operatorGuidance:input.operatorGuidance?.slice(0,1500)??'',conversation:input.messages.slice(-12).map(m=>({kind:m.kind==='customer'?'customer':m.kind==='staff'?'staff':'assistant',text:redactSupportInput(m.text)}))};}
