export function identifier(v:any){if(typeof v!=='string'||!/^[\w-]{43}$/.test(v))throw new SecurityError('معرّف غير صالح.');return v}
async function assertSessionTx(tx:Transaction,c:{uid:string;sid:string}){const [s,p]=await Promise.all([tx.get(sessionRef(c.sid)),tx.get(profileRef(c.uid))]);const v=s.data();if(!v||v.uid!==c.uid||v.status!=='active'||v.expiresAtMs<=Date.now()||v.epoch!==data(p).epoch)throw new SecurityError('تم إبطال الجلسة.',401,'session-revoked');return data(p)}
