export async function addTrusted(c:SecurityContext,input:any){const id=opaque(),deviceToken=opaque(),now=Date.now();await db.runTransaction(async tx=>{const consume=await consumeSecurityGrant(tx,c,input.stepUpToken,'trusted.add');consume();tx.create(doc('orinTrustedDevices',id),{uid:c.uid,sessionId:c.sid,name:safeDevice({label:input.name??c.session.device.label}).label,tokenHash:digest(deviceToken),createdAt:now,lastUsedAt:now,expiresAt:now+SESSION_LIFE,epoch:c.session.epoch,revokedAt:null});audit(tx,c.uid,'TRUSTED_DEVICE_ADDED',c.sid,c.ip,{deviceId:id});});return {id,deviceToken,expiresAt:now+SESSION_LIFE}}
export async function proveTrusted(c:SecurityContext,input:any){const id=identifier(input.id),proof=identifier(input.deviceToken);await db.runTransaction(async tx=>{const d=await tx.get(doc('orinTrustedDevices',id)),v=d.data();if(!v||v.uid!==c.uid||v.revokedAt||v.expiresAt<=Date.now()||v.epoch!==c.session.epoch||!equal(v.tokenHash,digest(proof)))throw new SecurityError('هذا الجهاز غير موثوق. يلزم التحقق الأمني.',403);tx.update(d.ref,{lastUsedAt:Date.now(),sessionId:c.sid});});return {trusted:true}}
export async function deleteTrusted(c:SecurityContext,input:any){const id=identifier(input.id);await db.runTransaction(async tx=>{const d=await tx.get(doc('orinTrustedDevices',id));if(d.data()?.uid!==c.uid)throw new SecurityError('الجهاز غير موجود.',404);const consume=await consumeSecurityGrant(tx,c,input.stepUpToken,'trusted.delete');const sessions=await tx.get(db.collection('orinSecuritySessions').where('uid','==',c.uid));consume();tx.update(d.ref,{revokedAt:Date.now()});sessions.docs.filter(s=>s.data().trustedDeviceId===id).forEach(s=>tx.update(s.ref,{status:'revoked',revokedAt:Date.now()}));audit(tx,c.uid,'TRUSTED_DEVICE_REMOVED',c.sid,c.ip,{deviceId:id});});return {ok:true}}
export async function changePassword(c:SecurityContext,input:any){
 if(typeof input.password!=='string'||input.password.length<12||input.password.length>128)throw new SecurityError('استخدم كلمة مرور من 12 إلى 128 حرفًا.');
 await db.runTransaction(async tx=>{const consume=await consumeSecurityGrant(tx,c,input.stepUpToken,'password.change');consume()});await auth.updateUser(c.uid,{password:input.password});await auth.revokeRefreshTokens(c.uid);
 await db.runTransaction(async tx=>{const p=await tx.get(profileRef(c.uid));tx.set(p.ref,{epoch:data(p).epoch+1},{merge:true});audit(tx,c.uid,'PASSWORD_CHANGED',c.sid,c.ip);});return {ok:true,requiresLogin:true};
}
const rp=()=>{const rpID=process.env.ORIN_WEBAUTHN_RP_ID,origin=process.env.ORIN_WEBAUTHN_ORIGIN;if(!rpID||!origin||new URL(origin).protocol!=='https:'||new URL(origin).hostname!==rpID)throw new SecurityError('لم يُضبط نطاق مفاتيح المرور الآمن بعد.',503);return {rpID,origin}}
export async function passkeyOptions(c:SecurityContext,input:any){
 const {rpID,origin}=rp(),keys=await all('orinSecurityPasskeys',c.uid),challengeId=opaque(),now=Date.now();
 const options=await generateRegistrationOptions({rpName:'ORIN',rpID,userID:new Uint8Array(Buffer.from(digest(c.uid),'hex')),userName:c.token.email??c.uid,attestationType:'none',excludeCredentials:keys.filter(k=>!k.revokedAt).map(k=>({id:k.credentialId})),authenticatorSelection:{residentKey:'required',userVerification:'required'},supportedAlgorithmIDs:[-7,-257]});
 await db.runTransaction(async tx=>{const factorVersion=data(await tx.get(profileRef(c.uid))).factorVersion;const consume=await consumeSecurityGrant(tx,c,input.stepUpToken,'passkey.add');consume();tx.create(doc('orinSecurityChallenges',challengeId),{uid:c.uid,sid:c.sid,kind:'register',challenge:options.challenge,origin,rpID,expiresAt:now+CHALLENGE_LIFE,consumed:false,name:safeDevice({label:input.name||'Passkey'}).label,epoch:c.session.epoch,factorVersion});});return {challengeId,options};
}
async function consumeChallenge(c:SecurityContext,id:string,kind:string){return db.runTransaction(async tx=>{const profile=await assertSessionTx(tx,c);const d=await tx.get(doc('orinSecurityChallenges',identifier(id))),v=d.data();if(!v||v.uid!==c.uid||v.sid!==c.sid||v.kind!==kind||v.epoch!==c.session.epoch||(v.factorVersion??0)!==profile.factorVersion||v.consumed||v.expiresAt<=Date.now())throw new SecurityError('انتهى التحقق الأمني. ابدأ من جديد.',401);tx.update(d.ref,{consumed:true});return v});}
export async function verifyPasskey(c:SecurityContext,input:any){
 const challenge=await consumeChallenge(c,input.challengeId,'register');let result;try{result=await verifyRegistrationResponse({response:input.response,expectedChallenge:challenge.challenge,expectedOrigin:challenge.origin,expectedRPID:challenge.rpID,requireUserVerification:true,supportedAlgorithmIDs:[-7,-257]})}catch{throw new SecurityError('تعذر التحقق من مفتاح المرور.',400)}
 if(!result.verified||!result.registrationInfo)throw new SecurityError('لم يتم التحقق من مفتاح المرور.',400);const info=result.registrationInfo,credential=info.credential,id=digest(credential.id),now=Date.now();
 await db.runTransaction(async tx=>{const profile=await assertSessionTx(tx,c);if((challenge.factorVersion??0)!==profile.factorVersion)throw new SecurityError('تغيرت إعدادات الأمان. أعد التحقق.',409);const existing=await tx.get(doc('orinSecurityPasskeys',id));if(existing.exists)throw new SecurityError('مفتاح المرور مسجل مسبقًا.',409);tx.create(existing.ref,{uid:c.uid,credentialId:credential.id,publicKey:Buffer.from(credential.publicKey).toString('base64url'),counter:credential.counter,transports:credential.transports??[],name:challenge.name,createdAt:now,lastUsedAt:null,revokedAt:null});audit(tx,c.uid,'PASSKEY_ADDED',c.sid,c.ip,{passkeyId:id});});return {ok:true,id};
}
export async function deletePasskey(c:SecurityContext,input:any){const id=String(input.id??'');if(!/^[a-f0-9]{64}$/.test(id))throw new SecurityError('معرّف غير صالح.');await db.runTransaction(async tx=>{const d=await tx.get(doc('orinSecurityPasskeys',id));if(d.data()?.uid!==c.uid)throw new SecurityError('المفتاح غير موجود.',404);const consume=await consumeSecurityGrant(tx,c,input.stepUpToken,'passkey.delete');consume();tx.update(d.ref,{revokedAt:Date.now()});audit(tx,c.uid,'PASSKEY_REMOVED',c.sid,c.ip,{passkeyId:id});});return {ok:true}}
export async function passkeyAuthOptions(c:SecurityContext,input:any){const factorVersion=data(await profileRef(c.uid).get()).factorVersion;const {rpID,origin}=rp(),action=actionName(input.action),keys=(await all('orinSecurityPasskeys',c.uid)).filter(k=>!k.revokedAt);if(!keys.length)throw new SecurityError('لا توجد مفاتيح مرور مسجلة.',409);const options=await generateAuthenticationOptions({rpID,userVerification:'required',allowCredentials:keys.map(k=>({id:k.credentialId,transports:k.transports}))}),challengeId=opaque();await doc('orinSecurityChallenges',challengeId).create({uid:c.uid,sid:c.sid,kind:'authenticate',factorVersion,action,challenge:options.challenge,origin,rpID,expiresAt:Date.now()+CHALLENGE_LIFE,consumed:false,epoch:c.session.epoch});return {challengeId,options}}
export async function verifyPasskeyAuth(c:SecurityContext,input:any){const challenge=await consumeChallenge(c,input.challengeId,'authenticate'),id=digest(String(input.response?.id??'')),d=await doc('orinSecurityPasskeys',id).get(),v=d.data();if(!v||v.uid!==c.uid||v.revokedAt)throw new SecurityError('مفتاح المرور غير صالح.',403);let result;try{result=await verifyAuthenticationResponse({response:input.response,expectedChallenge:challenge.challenge,expectedOrigin:challenge.origin,expectedRPID:challenge.rpID,credential:{id:v.credentialId,publicKey:Buffer.from(v.publicKey,'base64url'),counter:v.counter,transports:v.transports},requireUserVerification:true})}catch{throw new SecurityError('تعذر التحقق من مفتاح المرور.',401)}if(!result.verified)throw new SecurityError('فشل التحقق من المفتاح.',401);const stepUpToken=opaque(),now=Date.now();await db.runTransaction(async tx=>{const profile=await assertSessionTx(tx,c);const fresh=await tx.get(d.ref);if(fresh.data()?.revokedAt||fresh.data()?.counter!==v.counter)throw new SecurityError('تغير مفتاح المرور. أعد المحاولة.',409);tx.update(d.ref,{counter:result.authenticationInfo.newCounter,lastUsedAt:now});tx.create(doc('orinSecurityGrants',digest(stepUpToken)),{uid:c.uid,sid:c.sid,epoch:c.session.epoch,factorVersion:profile.factorVersion,action:challenge.action,expiresAt:now+STEPUP_LIFE,consumed:false});});return {stepUpToken,expiresAt:now+STEPUP_LIFE}}
/** Passwordless login: discoverable credential + required authenticator user verification. */
export async function passkeyLoginOptions(meta:RequestMeta){const {rpID,origin}=rp(),challengeId=opaque(),options=await generateAuthenticationOptions({rpID,userVerification:'required'});await doc('orinSecurityChallenges',challengeId).create({kind:'passkey-login',challenge:options.challenge,origin,rpID,expiresAt:Date.now()+CHALLENGE_LIFE,consumed:false});return {challengeId,options}}
export async function passkeyLoginVerify(input:any,meta:RequestMeta){
 const challenge=await db.runTransaction(async tx=>{const d=await tx.get(doc('orinSecurityChallenges',identifier(input.challengeId))),v=d.data();if(!v||v.kind!=='passkey-login'||v.consumed||v.expiresAt<=Date.now())throw new SecurityError('انتهى طلب الدخول.',401);tx.update(d.ref,{consumed:true});return v});
 const id=digest(String(input.response?.id??'')),d=await doc('orinSecurityPasskeys',id).get(),v=d.data();if(!v||v.revokedAt)throw new SecurityError('مفتاح المرور غير صالح.',401);const providerUser=await availableUser(v.uid);meta={...meta,providerValidAfter:providerUser.tokensValidAfterTime??''};let result;
 try{result=await verifyAuthenticationResponse({response:input.response,expectedChallenge:challenge.challenge,expectedOrigin:challenge.origin,expectedRPID:challenge.rpID,credential:{id:v.credentialId,publicKey:Buffer.from(v.publicKey,'base64url'),counter:v.counter,transports:v.transports},requireUserVerification:true})}catch{await db.runTransaction(async tx=>{audit(tx,v.uid,'LOGIN_FAILED',null,meta.ip,{reason:'passkey'})});throw new SecurityError('تعذر التحقق من مفتاح المرور.',401)}
 if(!result.verified)throw new SecurityError('مفتاح المرور غير صالح.',401);let created:ReturnType<typeof sessionRecord>|null=null;
 await db.runTransaction(async tx=>{const [f,p]=await Promise.all([tx.get(d.ref),tx.get(profileRef(v.uid))]);if(f.data()?.revokedAt||f.data()?.counter!==v.counter)throw new SecurityError('تغير المفتاح. أعد المحاولة.',409);created=sessionRecord(v.uid,data(p).epoch,{...meta,device:input.device});tx.update(d.ref,{counter:result.authenticationInfo.newCounter,lastUsedAt:Date.now()});tx.create(sessionRef(created.sid),created.record);audit(tx,v.uid,'LOGIN_SUCCESS',created.sid,meta.ip,{factor:'passkey'});});return bundle(created!);
}
/** Shared per-IP endpoint budget; keys are IP hashes and never contain credentials. */
export async function securityRequestBudget(ip:string|null){if(!ip)return;return securityBudget('ip:'+ip,300)}
export async function securityActorBudget(uid:string){return securityBudget('uid:'+uid,60)}
async function securityBudget(scope:string,limit:number){const now=Date.now(),id=digest(scope);await db.runTransaction(async tx=>{const d=await tx.get(doc('orinSecurityRateLimits',id)),v=d.data(),reset=now-(v?.windowStart??0)>=60_000;if(!reset&&(v?.count??0)>=limit)throw new SecurityError('محاولات كثيرة. حاول بعد دقيقة.',429);tx.set(d.ref,{windowStart:reset?now:v!.windowStart,count:reset?1:v!.count+1,expiresAt:now+60_000});});}
