export const SECTION_ROUTES:Record<string,string>={home:'/',real:'/markets',demo:'/trade',wallet:'/positions',account:'/settings',admin:'/admin'};
const allowed=/^\/(?:$|markets(?:\/(?:favorites|[A-Z0-9]{2,12}-[A-Z0-9]{2,12}))?$|trade(?:\/(?:indicators|drawings|alerts))?$|positions$|settings(?:\/(?:account|appearance|security|notifications|chart|about|admin|language|devices|privacy|documents|support|referral|agent|two-factor|authenticator|data))?$|notifications(?:\/[A-Za-z0-9:_-]+)?$|admin(?:\/(?:dashboard|notifications|audit|users|content|requests|contracts|programs|kyc|accounts|wallets|deposits|withdrawals|approvals|trading|markets|bonus|referrals|team|agencies|badges|configuration|security|staff|tickets))?$|activity$|transfer$|deposit$|withdraw$|documents$|privacy$|terms$|account\/security$|support$|referral(?:\/tree)?$|badges$|bonus$|agent$|invitations$|contracts\/[A-Za-z0-9:_-]+(?:\/(?:confirm|success))?$|transactions\/[A-Za-z0-9:_-]+$|announcements\/[A-Za-z0-9:_-]+$)/;
export function safeDestination(value:unknown):string {if(typeof value!=='string'||value.length>300)return '/notifications';let path:string;try{path=decodeURIComponent(value)}catch{return '/notifications'}if(!allowed.test(path))return '/notifications';return path;}
export function sectionForPath(path:string){if(path.startsWith('/settings'))return 'account';if(path.startsWith('/admin'))return 'admin';if(/^\/markets\/[A-Z0-9]+-[A-Z0-9]+$/.test(path))return 'demo';if(path.startsWith('/markets'))return 'real';if(path.startsWith('/trade')||path==='/invitations'||path.startsWith('/contracts/'))return 'demo';if(path.startsWith('/positions')||path.startsWith('/transactions/'))return 'wallet';return 'home';}
