/** Reviewed application knowledge, shipped with the release. Never editable by chat input. */
export const SUPPORT_KNOWLEDGE_VERSION='orin-1.6.1-2026-10-06';
export type SupportKnowledgeDocument={id:string;title:string;content:string};
export const SUPPORT_KNOWLEDGE:readonly SupportKnowledgeDocument[]=[
 {id:'scope',title:'ORIN support scope',content:'ORIN support explains how to use this application. It cannot execute trades, change balances, approve payments, recover passwords, verify identity, remove restrictions or promise a financial return. Those actions require the relevant authenticated application workflow or an authorized human. Never request passwords, PINs, OTPs, recovery codes, seed phrases or private keys.'},
 {id:'accounts',title:'Real and demo accounts',content:'Switch accounts from the account selector inside the existing home balance card. The green badge حقيقي identifies real accounts. The orange badge تجريبي identifies simulated funds. Demo money is separate from real money and cannot be withdrawn. Account switching should preserve the app session without a page reload.'},
 {id:'demo',title:'Demo balance and transfers',content:'Only demo accounts show ضبط الرصيد. The user can set a USD demo balance; setting it replaces the demo total, assigns it to the futures pocket and clears the perpetual pocket. Demo transfer moves existing simulated funds between futures and perpetual pockets without changing their total. Adjustment and transfer are blocked when a contract has reserved funds. Demo deposit/withdraw actions are disabled. A support message never authorizes an adjustment.'},
 {id:'real-transfers',title:'Real financial operations',content:'The shipped Spark client does not provide a real futures/perpetual transfer or execution engine. A visible account or transfer screen is not evidence that real trading, deposits, withdrawals or ORIN Pay settlement are enabled. Only the actual authenticated payment or trading screen and trusted backend can establish availability. Do not supply a payment address, promise activation, invent a transaction status or tell a user to send funds outside an approved in-app payment instruction.'},
 {id:'market',title:'Market card and charts',content:'The market card shows source data for the selected asset. The small chart uses closed historical 15-minute candles covering 24 hours; it is intentionally calm and not a live-tick animation. Kraken, Bitstamp or Coinbase may provide supported crypto/USD history. A missing or interrupted feed is a data-connection issue, not proof of a zero price. TradingView is the separate main chart. Support must not change its settings or invent missing chart points.'},
 {id:'positions',title:'Positions and activity',content:'المراكز displays open and closed internal contracts, search and contract details. These are not automatically exchange futures orders. Recent transactions and account statements are reached through settings/activity. A statement must reflect recorded entries. For a disputed result or missing payment, ask for the non-secret transaction reference and hand the conversation to support.'},
 {id:'settings',title:'Settings and language',content:'Settings contain profile, appearance/language, notifications, security, chart preferences and account activity. Arabic, English, Turkish and German interface translations are supported. Changing interface language does not change a financial account currency or convert balances. Profile updates apply to the signed-in account.'},
 {id:'security',title:'Account security workflows',content:'Security features must be read from the actual security screen. A compiled screen is not proof that a server service is deployed. ORIN app lock, when configured on Android, uses a device PIN or system biometric prompt; support never collects either. TOTP is enabled only after a successful first verification. Recovery codes are single-use. Passkey private keys stay with the device/credential provider. Session location, if shown from IP, is approximate, not GPS. Never claim to have ended a session or changed security from chat.'},
 {id:'referral',title:'Invitations',content:'دعوة صديق opens the referral page with the user’s own code/link and actual recorded referral activity when available. A referral code can be supplied in the optional registration field. A code or invitation does not guarantee a reward; reward eligibility and amounts depend on the published program terms and verified backend records. Do not fabricate invited-user counts or reward balances.'},
 {id:'support',title:'Messages and human assistance',content:'Support messages are saved to the signed-in user’s own conversation. The conversation menu offers طلب متابعة من موظف. A requested handoff does not mean a person is online or that a response time is guaranteed. Adam is ORIN’s automated support assistant, presented as Adam from ORIN support. He answers transparently about being automated when asked and never pretends to be a human. A reply exists only after a real model answers successfully. If the model is unavailable, the original user message remains saved and the conversation can be handed to the team.'},
];

/** Data minimization before sending a user-authored message to the inference service. */
export function redactSupportInput(value:string){
 return value.slice(0,2000)
  .replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,'[email omitted]')
  .replace(/(?:https?:\/\/|otpauth:\/\/|file:\/\/|data:)[^\s]+/gi,'[link omitted]')
  .replace(/\b(?:[a-f0-9]{6}-){3}[a-f0-9]{6}\b|\b[a-f0-9]{24}\b/gi,'[recovery code omitted]')
  .replace(/(?:password|passwd|secret|recovery\s*code|pin|otp|رمز\s*(?:التحقق|الاسترداد)|كلمة\s*(?:المرور|السر))\s*(?:[:=]|is|هو|هي)\s*\S+/gi,'[credential omitted]')
  .replace(/\b(?:sk-|eyJ)[A-Za-z0-9_.-]{12,}\b/g,'[credential omitted]')
  .replace(/[A-Za-z0-9_+\/=.-]{32,}/g,'[long identifier omitted]')
  .replace(/[0-9٠-٩۰-۹]{4,}/g,'[number omitted]');
}
